# ----------------------------------------------------------------- data
def api(url, payload=None):
    headers = {"Accept": "application/vnd.github+json", "User-Agent": "bonevane-stats"}
    if TOKEN:
        headers["Authorization"] = f"Bearer {TOKEN}"
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, headers=headers)
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read().decode())


def contributions():
    q = """query($login:String!,$from:DateTime!,$to:DateTime!){user(login:$login){createdAt
      contributionsCollection(from:$from,to:$to){contributionCalendar{weeks{contributionDays{date contributionCount}}}}}}"""
    first = api("https://api.github.com/graphql", {"query": "query($l:String!){user(login:$l){createdAt}}",
                                                    "variables": {"l": LOGIN}})
    created = dt.datetime.fromisoformat(first["data"]["user"]["createdAt"].replace("Z", "+00:00"))
    now = dt.datetime.now(dt.timezone.utc)
    days = {}
    start = created
    while start < now:
        end = min(start + dt.timedelta(days=365), now)
        res = api("https://api.github.com/graphql", {"query": q, "variables": {
            "login": LOGIN, "from": start.isoformat(), "to": end.isoformat()}})
        for w in res["data"]["user"]["contributionsCollection"]["contributionCalendar"]["weeks"]:
            for d in w["contributionDays"]:
                days[d["date"]] = d["contributionCount"]
        start = end
    dates = sorted(days)
    total = sum(days.values())
    longest = run = 0
    for d in dates:
        run = run + 1 if days[d] > 0 else 0
        longest = max(longest, run)
    current = 0
    i = len(dates) - 1
    if i >= 0 and days[dates[i]] == 0:  # today not counted against the streak yet
        i -= 1
    while i >= 0 and days[dates[i]] > 0:
        current += 1
        i -= 1
    this_year = sum(v for k, v in days.items() if k.startswith(str(now.year)))
    return dict(total=total, current=current, longest=longest, this_year=this_year,
                since=created.year)


def languages():
    repos, page = [], 1
    while True:
        batch = api(f"https://api.github.com/users/{LOGIN}/repos?per_page=100&type=owner&page={page}")
        repos += batch
        if len(batch) < 100:
            break
        page += 1
    size, count = {}, {}
    for r in repos:
        if r.get("fork") or r.get("archived"):
            continue
        for lang, b in api(r["languages_url"]).items():
            if lang in EXCLUDE:
                continue
            size[lang] = size.get(lang, 0) + b
            count[lang] = count.get(lang, 0) + 1
    # same weighting idea as github-readme-stats size_weight=0.5,count_weight=0.5
    score = {k: math.sqrt(size[k]) * math.sqrt(count[k]) for k in size}
    tot = sum(score.values()) or 1
    ranked = sorted(score.items(), key=lambda kv: -kv[1])[:TOP_N]
    shown = sum(v for _, v in ranked) or 1
    return [(k, v / shown) for k, v in ranked]


# ----------------------------------------------------------------- drawing
def width(font, text, size):
    tbl = WIDTHS[font]
    return sum(tbl.get(c, tbl[" "]) for c in text) * size / 1000.0


def polar(cx, cy, rfun, n=72):
    pts = []
    for i in range(n):
        t = 2 * math.pi * i / n
        r = rfun(t)
        pts.append((cx + r * math.cos(t), cy + r * math.sin(t)))
    d = [f"M{pts[0][0]:.1f} {pts[0][1]:.1f}"]
    for i in range(n):
        p0, p1, p2, p3 = pts[i - 1], pts[i], pts[(i + 1) % n], pts[(i + 2) % n]
        d.append(f"C{p1[0] + (p2[0] - p0[0]) / 6:.1f} {p1[1] + (p2[1] - p0[1]) / 6:.1f} "
                 f"{p2[0] - (p3[0] - p1[0]) / 6:.1f} {p2[1] - (p3[1] - p1[1]) / 6:.1f} {p2[0]:.1f} {p2[1]:.1f}")
    return "".join(d) + "Z"


def cookie(cx, cy, R, lobes=9, depth=0.14):
    return polar(cx, cy, lambda t: R * (1 - depth * 0.5 * (1 - math.cos(lobes * t))))


def flower(cx, cy, R, petals=6, depth=0.3):
    return polar(cx, cy, lambda t: R * (1 - depth * (1 - abs(math.cos(petals * t / 2)) ** 0.9)))


def burst(cx, cy, R, spikes=10, depth=0.24):
    return polar(cx, cy, lambda t: R * (1 - depth * (0.5 - 0.5 * math.cos(spikes * t)) ** 1.6))


class Doc:
    def __init__(self):
        self.p = []

    def add(self, s):
        self.p.append(s)

    def text(self, x, y, s, font, size, fill, anchor="start", ls=0, opacity=None):
        op = f' opacity="{opacity}"' if opacity is not None else ""
        lsa = f' letter-spacing="{ls}"' if ls else ""
        self.add(f'<text x="{x:.1f}" y="{y:.1f}" font-family="\'{font}\'" font-size="{size}" fill="{fill}" '
                 f'text-anchor="{anchor}"{lsa}{op}>{escape(s)}</text>')


def render(t, c, langs):
    W, gap, PAD = 1280, 24, 48
    tw, th = (W - 2 * gap) / 3, 280
    lang_h = 300
    H = th + gap + lang_h
    d = Doc()
    tiles = [
        ("CONTRIBUTIONS", f"{c['total']:,}", f"since {c['since']}", "p_cont", "on_p_cont", "primary",
         lambda x, y: cookie(x, y, 46, 10, 0.12)),
        ("CURRENT STREAK", f"{c['current']}", "day" if c["current"] == 1 else "days", "t_cont", "on_t_cont",
         "tertiary", lambda x, y: burst(x, y, 46, 9, 0.28)),
        ("LONGEST STREAK", f"{c['longest']}", "days", "sc_high", "on_surface", "secondary",
         lambda x, y: flower(x, y, 46, 6, 0.3)),
    ]
    for i, (label, num, unit, bg, fg, base, shape) in enumerate(tiles):
        x0 = i * (tw + gap)
        d.add(f'<rect x="{x0:.1f}" y="0" width="{tw:.1f}" height="{th}" rx="40" fill="{t[bg]}"/>')
        d.add(f'<g class="spin"><path d="{shape(x0 + tw - PAD - 40, PAD + 40)}" fill="{t[base]}" opacity="0.9"/></g>')
        d.text(x0 + PAD, PAD + 17, label, "Medium", 22, t[fg], ls=2, opacity=0.85)
        d.text(x0 + PAD, 190, num, "Display", 96, t[fg], ls=-2)
        d.text(x0 + PAD, th - PAD, unit, "Medium", 24, t[fg], opacity=0.75)
    # languages tile
    y0 = th + gap
    d.add(f'<rect x="0" y="{y0}" width="{W}" height="{lang_h}" rx="40" fill="{t["sc"]}"/>')
    d.text(PAD, y0 + PAD + 17, "LANGUAGES I REACH FOR", "Medium", 22, t["on_variant"], ls=2)
    seg_colors = [t[k] for k in ("primary", "tertiary", "secondary", "seg4", "t_cont_strong", "outline")]
    bx, by, bw, bh = PAD, y0 + 104, W - 2 * PAD, 40
    clip = f'<clipPath id="bar"><rect x="{bx}" y="{by}" width="{bw}" height="{bh}" rx="{bh / 2}"/></clipPath>'
    d.add(f"<defs>{clip}</defs>")
    x = bx
    segs = []
    for i, (lang, share) in enumerate(langs):
        w = bw * share
        segs.append(f'<rect x="{x:.1f}" y="{by}" width="{max(w - 4, 1):.1f}" height="{bh}" fill="{seg_colors[i % 6]}"/>')
        x += w
    d.add(f'<g clip-path="url(#bar)">{"".join(segs)}</g>')
    cols = 3
    colw = bw / cols
    for i, (lang, share) in enumerate(langs):
        cx = bx + (i % cols) * colw
        cy = by + bh + 58 + (i // cols) * 52
        d.add(f'<circle cx="{cx + 10}" cy="{cy - 9}" r="10" fill="{seg_colors[i % 6]}"/>')
        d.text(cx + 32, cy, lang, "Title", 28, t["on_surface"])
        d.text(cx + 32 + width("Title", lang, 28) + 12, cy, f"{share * 100:.1f}%", "Regular", 24, t["on_variant"])
    css = "".join(f"@font-face{{font-family:'{k}';src:url(data:font/woff;base64,{v}) format('woff');}}"
                  for k, v in FONTS.items())

    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" role="img">'
            f"<title>GitHub stats: {c['total']:,} contributions, current streak {c['current']}, longest streak "
            f"{c['longest']}</title><style>{css}</style>" + "".join(d.p) + "</svg>")


def main(c=None, langs=None):
    c = c or contributions()
    langs = langs or languages()
    os.makedirs(OUT_DIR, exist_ok=True)
    for name, t in THEMES.items():
        with open(os.path.join(OUT_DIR, f"stats-{name}.svg"), "w") as f:
            f.write(render(t, c, langs))
    print(json.dumps(dict(contributions=c, languages=langs)))


if __name__ == "__main__":
    main()
